package com.xuhang.mealops.inventory.application;
import static org.assertj.core.api.Assertions.*; import java.math.*; import java.util.*; import java.util.concurrent.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.context.annotation.Import; import org.springframework.jdbc.core.JdbcTemplate; import com.xuhang.mealops.ingredient.application.IngredientRepository; import com.xuhang.mealops.ingredient.domain.*; import com.xuhang.mealops.inventory.domain.*; import com.xuhang.mealops.inventory.application.*; import com.xuhang.mealops.measurement.domain.*; import com.xuhang.mealops.support.PostgresTestConfiguration;
@SpringBootTest @Import(PostgresTestConfiguration.class) class InventoryConcurrencyAllocationCountIT { @Autowired InventoryConsumptionApplicationService service; @Autowired InventoryBatchRepository batches; @Autowired IngredientRepository ingredients; @Autowired JdbcTemplate jdbc; @Test void concurrentWinnerHasOneAllocation(){var i=ingredients.create(Ingredient.newIngredient(IngredientName.of("Concurrent allocation "+UUID.randomUUID())));batches.create(InventoryBatch.newBatch(i.id(),Quantity.of(new BigDecimal("500"),Unit.GRAM),null));var p=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var fs=List.of(p.submit(()->{start.await();try{service.consume(i.id(),new BigDecimal("400"),"g");return true;}catch(Exception e){return false;}}),p.submit(()->{start.await();try{service.consume(i.id(),new BigDecimal("400"),"g");return true;}catch(Exception e){return false;}}));start.countDown();assertThat(fs.get(0).get(20,TimeUnit.SECONDS)^fs.get(1).get(20,TimeUnit.SECONDS)).isTrue();assertThat(jdbc.queryForObject("select count(*) from inventory_transaction_allocation a join inventory_transaction t on t.id=a.transaction_id where t.ingredient_id=?",Integer.class,i.id())).isEqualTo(1);}catch(Exception e){throw new RuntimeException(e);}finally{p.shutdownNow();}}}
